// GENERATED by scripts/embed-host-script.sh from host/macmosh-host. Do not edit by hand.
// After any change to host/macmosh-host, regenerate it with: scripts/embed-host-script.sh
// (scripts/check.sh fails when this file is out of date.)

enum HostScriptSource {
    static let text = #"""
#!/bin/bash
# macmosh-host: the script MacMosh keeps on a workhorse (a Mac you reach from another Mac).
# It starts the desk server, prints the status report, manages desks and installs the login agent.
# Plain bash 3.2 (what macOS ships at /bin/bash): no associative arrays, no mapfile, no ${var,,}.
set -u

MACMOSH_HOST_VERSION=0.6.0
MACMOSH_PROTOCOL=1
AGENT_LABEL=io.github.shariqh.macmosh.host

MACMOSH_HOME="${MACMOSH_HOME:-$HOME/.macmosh}"
MACMOSH_SOCKET="${MACMOSH_SOCKET:-macmosh}"
# Homebrew's folders go at the END of PATH, so a stand-in tool earlier on PATH wins in tests.
PATH="$PATH:/opt/homebrew/bin:/usr/local/bin"
export MACMOSH_HOME MACMOSH_SOCKET PATH

TAB=$'\t'

# Every tmux call goes through this one function, so it always names the desk server's socket.
mm_tmux() { command tmux -L "$MACMOSH_SOCKET" "$@"; }

# ---------------------------------------------------------------- log

# One line per subcommand: an ISO 8601 time, the subcommand and the result.
# The log never makes a subcommand fail, and it is cut back when it grows past about 1 MB.
mm_log() {
    local log="$MACMOSH_HOME/host.log" size
    mkdir -p "$MACMOSH_HOME" 2>/dev/null || return 0
    if [ -f "$log" ]; then
        size=$(wc -c < "$log" 2>/dev/null | tr -d ' ')
        if [ "${size:-0}" -gt 1000000 ]; then
            tail -n 2000 "$log" > "$log.$$.tmp" 2>/dev/null && mv "$log.$$.tmp" "$log" 2>/dev/null
        fi
    fi
    printf '%s\t%s\t%s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$1" "$2" >> "$log" 2>/dev/null
    return 0
}

# ---------------------------------------------------------------- small helpers

# Tabs and newlines become spaces, so one value can never break the record around it.
mm_clean() { printf '%s' "$1" | tr '\t\n\r' '   '; }

mm_valid_desk_name() {
    case "$1" in
        '' | *[!A-Za-z0-9_-]*) return 1 ;;
    esac
    [ "${#1}" -le 64 ]
}

mm_server_up() { mm_tmux list-sessions >/dev/null 2>&1; }

# The user logged in at the screen, or nothing.
mm_console_user() {
    local who
    who=$(stat -f %Su /dev/console 2>/dev/null)
    case "$who" in
        root | loginwindow | _mbsetupuser) who="" ;;
    esac
    printf '%s' "$who"
}

# ---------------------------------------------------------------- start

# The file tmux itself would read: ~/.tmux.conf, otherwise the XDG one.
mm_user_tmux_conf() {
    if [ -f "$HOME/.tmux.conf" ]; then
        printf '%s' "$HOME/.tmux.conf"
    else
        printf '%s' "${XDG_CONFIG_HOME:-$HOME/.config}/tmux/tmux.conf"
    fi
}

mm_write_tmux_conf() {
    mkdir -p "$MACMOSH_HOME" || return 1
    {
        echo '# MacMosh defaults. Your own tmux settings are loaded next, so your settings win,'
        echo '# except the two after them that desks need: the server stays up with no desk open,'
        echo '# and a desk stays open when its last terminal leaves.'
        echo 'set -g mouse on'
        echo 'set -g history-limit 50000'
        echo "source-file -q \"$(mm_user_tmux_conf)\""
        echo 'set -s exit-empty off'
        echo 'set -g destroy-unattached off'
    } > "$MACMOSH_HOME/tmux.conf"
}

cmd_start() {
    if mm_server_up; then
        mm_set_hook
        mm_log start "already up"
        return 0
    fi
    if ! mm_write_tmux_conf; then
        mm_log start "failed: cannot write tmux.conf"
        echo "macmosh-host: cannot write $MACMOSH_HOME/tmux.conf" >&2
        return 5
    fi
    mm_tmux -f "$MACMOSH_HOME/tmux.conf" start-server >/dev/null 2>&1
    if mm_server_up; then
        # The hook first, so a reopened desk whose shell ends at once is handled like any other.
        # Nothing is dropped here: a server that was down says nothing about why, so every
        # definition stays. A line that is not reopened is hidden by the menu, desk-new replaces it,
        # and attach makes the desk again from it.
        mm_set_hook
        mm_reopen_desks
        mm_log start "started"
        return 0
    fi
    mm_log start "failed: server did not start"
    echo "macmosh-host: the desk server did not start" >&2
    return 5
}

# ---------------------------------------------------------------- desks

DESKS_FILE_NAME=desks.tsv

mm_desks_file() { printf '%s' "$MACMOSH_HOME/$DESKS_FILE_NAME"; }

# A leading ~ (alone or before a slash) means the home folder. Anything else is left as it is.
mm_expand_tilde() {
    local tilde='~'
    case "$1" in
        "$tilde") printf '%s' "$HOME" ;;
        "$tilde"/*) printf '%s' "$HOME/${1#"$tilde"/}" ;;
        *) printf '%s' "$1" ;;
    esac
}

# True when the text has a tab or a newline in it, which would break a line of desks.tsv.
mm_has_tab_or_newline() {
    case "$1" in
        *"$TAB"* | *$'\n'*) return 0 ;;
    esac
    return 1
}

# Every awk that compares a desk name with the first field adds "" to both sides. Without it awk
# compares names that look like numbers as numbers, so "7" would match "007" and "1000" would match "1e3".

# The line of desks.tsv for one desk, or nothing.
mm_def_line() {
    local file
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    awk -F '\t' -v n="$1" '($1 "") == (n "") { print; exit }' "$file"
}

# The tmux id ($n) of the session with exactly this name, or nothing. Not has-session -t "=name": when
# no session has the name, tmux also matches it against an attached client's tty (ttys003), and then
# stands for the session that client shows.
mm_session_id() {
    mm_tmux list-sessions -F "#{session_id}$TAB#{session_name}" 2>/dev/null |
        awk -F '\t' -v n="$1" '($2 "") == (n "") { print $1; exit }'
}

mm_session_exists() { [ -n "$(mm_session_id "$1")" ]; }

# Reads one line of desks.tsv into d_name, d_reopen, d_keep, d_permanent, d_folder and d_command.
# A line is: name, reopen (0 or 1), keep (0 or 1), permanent (0 or 1), folder, startup command.
# A line written before 0.5.0 has no permanent field: its folder comes fourth. A folder always starts
# with /, which tells the two apart, and a desk from such a line is not permanent.
mm_read_def() {
    local rest="$1"
    d_name="" d_reopen="" d_keep="" d_permanent=0 d_folder="" d_command=""
    d_name="${rest%%"$TAB"*}"
    [ "$d_name" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    d_reopen="${rest%%"$TAB"*}"
    [ "$d_reopen" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    d_keep="${rest%%"$TAB"*}"
    [ "$d_keep" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    case "$rest" in
        /*) ;;
        *"$TAB"*)
            d_permanent="${rest%%"$TAB"*}"
            rest="${rest#*"$TAB"}"
            ;;
    esac
    d_folder="${rest%%"$TAB"*}"
    if [ "$d_folder" != "$rest" ]; then d_command="${rest#*"$TAB"}"; fi
    return 0
}

# Writes desks.tsv without the line for one desk, through a temporary file and mv. The caller holds the lock.
mm_drop_def_line() {
    local file tmp
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
    if ! awk -F '\t' -v n="$1" '($1 "") != (n "")' "$file" > "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        return 1
    fi
    return 0
}

# The desk server's process id, or nothing when no server answers. It never starts a server.
mm_server_pid() { mm_tmux display-message -p '#{pid}' 2>/dev/null; }

# --- Removing a desk when its last shell exits.
#
# The desk server runs a hook when a session closes. It waits a moment, then runs
# "<this script> desk-closed <desk> <server pid>", and desk-closed removes the desk's definition only
# when that same server still answers. An exit in a desk's last shell leaves the server running (its
# exit-empty is off). Shutting the server down (kill-server, restart-server, a signal, the Mac
# restarting) ends it, so a hook from it finds no server or a different one, and the definition stays.
# Seen with tmux 3.8: a server that is shutting down runs no session-closed hook at all.
#
# The wait is a minute. It runs inside the desk server, so a restart or a logout that ends the server
# within that minute ends the wait too, and the definition stays. At an Apple-menu restart or logout,
# macOS first quits the apps, which can take a while, and only then ends the server; a desk whose
# program waited on one of those apps closes in between. The cost: after a real exit, the stale line
# stays (hidden by the menu) for up to a minute, and a desk exited less than a minute before a restart
# comes back once. MACMOSH_HOOK_DELAY (whole seconds) changes the wait, for the tests.
#
# The hook lives in one member of the session-closed hook array, so the user's own hooks stay. start,
# status, attach, desk-new and window-new set it again each time: a server started by an older script
# gets it with no restart, and a hook cleared by reloading the user's tmux settings comes back.
MM_HOOK='session-closed[1089]'
MM_HOOK_DELAY="${MACMOSH_HOOK_DELAY:-60}"
case "$MM_HOOK_DELAY" in
    '' | *[!0-9]*) MM_HOOK_DELAY=60 ;;
esac

mm_set_hook() {
    local prefix
    prefix="MACMOSH_HOME=$(mm_shell_quote "$MACMOSH_HOME") MACMOSH_SOCKET=$(mm_shell_quote "$MACMOSH_SOCKET")"
    prefix="$prefix $(mm_shell_quote "$(mm_self_path)") desk-closed"
    # The prefix is kept in a user option and put into the command when the hook runs, so a path with
    # odd characters never passes through tmux's own command parser. q: quotes the desk name for sh.
    # destroy-unattached is forced off here too (see mm_write_tmux_conf), for a server that is already
    # running or whose user settings were loaded again.
    # shellcheck disable=SC2016  # the #{...} parts are tmux formats, expanded when the hook runs
    mm_tmux set-option -g destroy-unattached off \; \
        set-option -g @macmosh-desk-closed "$prefix" \; \
        set-hook -g "$MM_HOOK" "run-shell -b -d $MM_HOOK_DELAY '#{@macmosh-desk-closed} #{q:hook_session_name} #{pid} >/dev/null 2>&1 || true'" \
        >/dev/null 2>&1
    return 0
}

# This script's own full path, so a desk can run it again later.
mm_self_path() {
    local p="$0"
    case "$p" in
        */*) ;;
        *) p=$(command -v -- "$p" 2>/dev/null || printf '%s' "$p") ;;
    esac
    case "$p" in
        /*) ;;
        *) p="$PWD/${p#./}" ;;
    esac
    printf '%s' "$p"
}

# Text quoted for a shell: inside single quotes, with each ' written as '\''.
mm_shell_quote() {
    local text="$1" quote="'" out=""
    while :; do
        case "$text" in
            *"$quote"*)
                out="$out${text%%"$quote"*}'\''"
                text="${text#*"$quote"}"
                ;;
            *) break ;;
        esac
    done
    printf "'%s'" "$out$text"
}

# Creates the session for a desk: in its folder, then types the startup command exactly as written.
# For a desk that keeps its command running, it types "<this script> keep <desk>" instead, and that
# runs the command again whenever it ends.
# The keys wait in the terminal's input queue, so a shell that is slow to start still receives them.
# The keys go to the new session's id, never "=name" (see mm_session_id). MM_NEW_SID holds that id, or
# nothing when no session was made, so a caller that rolls back kills only the session made here.
mm_create_session() {
    # $1 name, $2 folder, $3 startup command (may be empty), $4 keep: 1 or 0 (optional)
    local folder="$2" typed="$3" sid
    MM_NEW_SID=""
    if [ ! -d "$folder" ]; then
        mm_log "create-desk" "$1: folder is gone, using the home folder"
        folder="$HOME"
    fi
    if [ "${4:-0}" = 1 ] && [ -n "$typed" ]; then
        typed="$(mm_shell_quote "$(mm_self_path)") keep $1"
    fi
    sid=$(mm_tmux new-session -d -P -F '#{session_id}' -s "$1" -c "$folder" 2>/dev/null) || return 1
    MM_NEW_SID="$sid"
    [ -n "$sid" ] || return 1
    if [ -n "$typed" ]; then
        mm_tmux send-keys -t "$sid:" -l -- "$typed" || return 1
        mm_tmux send-keys -t "$sid:" Enter || return 1
    fi
    return 0
}

# Recreates the desks marked reopen. Called by start, only when it has just started the server.
# This includes a permanent desk that was closed: it is marked reopen, so it opens again.
# Each desk is made under the desk list's lock, with its line read again there, so a desk-new or a
# desk-remove of the same name running at the same moment goes wholly before or wholly after it.
# The loop reads the list it opened, which a desk-rename replaces with mv, so a second pass over the
# current list opens a desk renamed during the first. It skips the names the first pass handled.
# Accepted: a desk made or renamed during the first pass and then exited before the second pass
# reaches it is opened once more.
mm_reopen_desks() {
    MM_REOPENED=""
    mm_reopen_pass 1
    mm_reopen_pass 2
    return 0
}

# One pass of mm_reopen_desks. Pass 1 records each name in MM_REOPENED; pass 2 skips those names.
mm_reopen_pass() {
    local file line name
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    while IFS= read -r line || [ -n "$line" ]; do
        mm_read_def "$line"
        mm_valid_desk_name "$d_name" || continue
        [ "$d_reopen" = 1 ] || continue
        name="$d_name"
        case "$MM_REOPENED" in
            *" $name "*) continue ;;
        esac
        if [ "$1" = 1 ]; then MM_REOPENED="$MM_REOPENED $name "; fi
        if ! mm_lock; then
            mm_log start "could not reopen $name: could not lock the desk list"
            continue
        fi
        line=$(mm_def_line "$name")
        if [ -n "$line" ]; then mm_read_def "$line"; fi
        if [ -n "$line" ] && [ "$d_reopen" = 1 ] && ! mm_session_exists "$name"; then
            mm_create_session "$name" "$d_folder" "$d_command" "$d_keep" || mm_log start "could not reopen $name"
        fi
        mm_release_lock
    done < "$file"
    return 0
}

# --- The lock around desks.tsv: a folder made with mkdir. One writer at a time. A lock folder older
# than 30 seconds belongs to a writer that died, so it is removed.

MM_LOCK_HELD=0

mm_unlock() {
    if [ "$MM_LOCK_HELD" = 1 ]; then
        MM_LOCK_HELD=0
        rmdir "$MACMOSH_HOME/lock" 2>/dev/null
    fi
    return 0
}

# Takes the lock, waiting up to 5 seconds. Releases it on every way out (the trap), including
# an error part-way and a signal.
mm_lock() {
    local lock="$MACMOSH_HOME/lock" tries=0 mtime now
    mkdir -p "$MACMOSH_HOME" || return 1
    while ! mkdir "$lock" 2>/dev/null; do
        mtime=$(/usr/bin/stat -f %m "$lock" 2>/dev/null)
        case "$mtime" in
            '' | *[!0-9]*) mtime="" ;;
        esac
        now=$(date +%s)
        if [ -n "$mtime" ] && [ $((now - mtime)) -gt 30 ] && rmdir "$lock" 2>/dev/null; then
            continue
        fi
        tries=$((tries + 1))
        [ "$tries" -lt 50 ] || return 1
        sleep 0.1
    done
    MM_LOCK_HELD=1
    trap mm_unlock EXIT
    trap 'exit 130' INT HUP
    trap 'exit 143' TERM
    return 0
}

mm_release_lock() {
    mm_unlock
    trap - EXIT INT HUP TERM
}

# If the desk server is down: with nobody logged in at the screen, exit 3. Otherwise ask macOS to
# run the login agent, wait up to 5 seconds, and exit 5 if the server is still down.
# This is the only way these subcommands get a server. They never start one themselves, because a
# tmux server started from an ssh login can't read the keychain.
mm_require_server() {
    # $1 the subcommand, for the log
    local who n=0
    if mm_server_up; then return 0; fi
    who=$(mm_console_user)
    if [ -z "$who" ]; then
        echo "Nobody is logged in at this Mac's screen, so desks can't start. Log in first." >&2
        mm_log "$1" "nobody logged in"
        exit 3
    fi
    launchctl kickstart "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1
    while [ "$n" -lt 10 ]; do
        if mm_server_up; then return 0; fi
        sleep 0.5
        n=$((n + 1))
    done
    if mm_server_up; then return 0; fi
    echo "The desk server didn't start." >&2
    mm_log "$1" "server did not start"
    exit 5
}

# A usage error: a message, a log line and exit 2.
mm_usage_error() {
    # $1 subcommand, $2 message
    echo "macmosh-host: $2" >&2
    mm_log "$1" "usage error"
    exit 2
}

cmd_desk_new() {
    local name="" folder="" reopen=1 keep=0 permanent=0 command="" npos=0 file tmp old
    while [ $# -gt 0 ]; do
        case "$1" in
            # A new desk comes back after a restart unless told not to. --reopen is still accepted.
            --reopen) reopen=1 ;;
            --no-reopen) reopen=0 ;;
            --keep) keep=1 ;;
            --permanent) permanent=1 ;;
            --command)
                [ $# -ge 2 ] || mm_usage_error desk-new "--command needs a value"
                command="$2"
                shift
                ;;
            --*) mm_usage_error desk-new "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                case "$npos" in
                    1) name="$1" ;;
                    2) folder="$1" ;;
                    *) mm_usage_error desk-new "too many arguments" ;;
                esac
                ;;
        esac
        shift
    done
    [ "$npos" -eq 2 ] || mm_usage_error desk-new "usage: desk-new <name> <folder> [--no-reopen] [--permanent] [--keep] [--command <text>]"

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: a desk name uses letters, digits, - and _ only, up to 64 characters" >&2
        mm_log desk-new "refused: bad name"
        return 6
    fi
    # Check before expanding: $(...) drops a new line at the end of the text.
    if mm_has_tab_or_newline "$folder" || mm_has_tab_or_newline "$command"; then
        echo "macmosh-host: a folder or command can't contain a tab or a new line" >&2
        mm_log desk-new "refused: tab or newline"
        return 6
    fi
    if [ "$keep" = 1 ] && [ -z "$command" ]; then
        echo "macmosh-host: there is nothing to keep running: --keep needs a --command" >&2
        mm_log desk-new "refused: keep without a command"
        return 6
    fi
    folder=$(mm_expand_tilde "$folder")
    case "$folder" in
        /*) ;;
        *)
            echo "macmosh-host: the folder must be a full path or start with ~" >&2
            mm_log desk-new "refused: folder is not a full path"
            return 6
            ;;
    esac
    if [ ! -d "$folder" ]; then
        echo "macmosh-host: no such folder: $folder" >&2
        mm_log desk-new "refused: no such folder"
        return 6
    fi

    mm_require_server desk-new
    mm_set_hook

    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-new "failed: lock"
        return 1
    fi
    # The name is taken by an open desk, or by a permanent one that is closed. A line that is neither
    # is left over (its last shell exited, or it ended with an older server) and is replaced.
    old=$(mm_def_line "$name")
    if [ -n "$old" ]; then mm_read_def "$old"; fi
    if mm_session_exists "$name" || { [ -n "$old" ] && [ "$d_permanent" != 0 ]; }; then
        mm_release_lock
        echo "macmosh-host: the desk $name already exists" >&2
        mm_log desk-new "refused: $name already exists"
        return 7
    fi
    # Save the definition first. The desk's shell may run "keep <desk>" the moment the session exists,
    # and keep reads this line. If the session can't be made, the line is taken back out.
    file=$(mm_desks_file)
    tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
    if ! {
        { [ ! -f "$file" ] || awk -F '\t' -v n="$name" '($1 "") != (n "")' "$file"; } &&
            printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$name" "$reopen" "$keep" "$permanent" "$folder" "$command"
    } > "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        mm_release_lock
        echo "macmosh-host: could not write the desk list" >&2
        mm_log desk-new "failed: $name could not be saved"
        return 1
    fi
    if ! mm_create_session "$name" "$folder" "$command" "$keep"; then
        if [ -n "$MM_NEW_SID" ]; then mm_tmux kill-session -t "$MM_NEW_SID" >/dev/null 2>&1; fi
        mm_drop_def_line "$name"
        mm_release_lock
        echo "macmosh-host: could not create the desk" >&2
        mm_log desk-new "failed: $name could not be created"
        return 1
    fi
    mm_release_lock
    mm_log desk-new "created $name"
    return 0
}

cmd_desk_remove() {
    local name="" kill=0 npos=0 had_def=0 had_session=0 sid
    while [ $# -gt 0 ]; do
        case "$1" in
            --kill) kill=1 ;;
            --*) mm_usage_error desk-remove "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                [ "$npos" -le 1 ] || mm_usage_error desk-remove "too many arguments"
                name="$1"
                ;;
        esac
        shift
    done
    [ "$npos" -eq 1 ] || mm_usage_error desk-remove "usage: desk-remove <name> [--kill]"

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log desk-remove "no such desk"
        return 4
    fi
    # No mm_require_server here: removing a desk never needs a server, and must never start one.
    # has-session and kill-session only talk to a server that is already running.
    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-remove "failed: lock"
        return 1
    fi
    if [ -n "$(mm_def_line "$name")" ]; then had_def=1; fi
    sid=$(mm_session_id "$name")
    if [ -n "$sid" ]; then had_session=1; fi
    if [ "$had_def" = 0 ] && { [ "$kill" = 0 ] || [ "$had_session" = 0 ]; }; then
        mm_release_lock
        echo "macmosh-host: no such desk: $name" >&2
        mm_log desk-remove "no such desk: $name"
        return 4
    fi
    if [ "$had_def" = 1 ]; then
        if ! mm_drop_def_line "$name"; then
            mm_release_lock
            echo "macmosh-host: could not write the desk list" >&2
            mm_log desk-remove "failed: $name could not be saved"
            return 1
        fi
    fi
    mm_release_lock
    if [ "$kill" = 1 ] && [ "$had_session" = 1 ]; then
        mm_tmux kill-session -t "$sid" >/dev/null 2>&1
    fi
    mm_log desk-remove "removed $name"
    return 0
}

# Renames a desk: its tmux session, if it has one, and the first field of its definition, if it has
# one. Everything else stays: the windows and what runs in them, the folder, the startup command and
# the reopen, keep and permanent fields. A rename closes no session, so the exit path never runs for it.
# With the desk server up, the new name is taken by an open desk or a permanent one, as for desk-new,
# and a line that is neither is left over from an exit and is replaced. With no server, any line takes
# it, because the desk waits to reopen at the next login.
cmd_desk_rename() {
    local old new taken file tmp up sid line
    [ $# -eq 2 ] || mm_usage_error desk-rename "usage: desk-rename <name> <new name>"
    old="$1"
    new="$2"
    if ! mm_valid_desk_name "$old" || ! mm_valid_desk_name "$new"; then
        mm_usage_error desk-rename "a desk name uses letters, digits, - and _ only, up to 64 characters"
    fi
    # No mm_require_server here, as for desk-remove: a closed desk is renamed in the list alone, and
    # has-session and rename-session only talk to a server that is already running.
    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-rename "failed: lock"
        return 1
    fi
    # Sessions are found by id, never by "=name" (see mm_session_id). With a server up, a closed desk
    # that is not permanent has exited and its line only waits for the exit path, so it is no desk to
    # rename. With none, every line is a desk waiting for the next login.
    up=0
    if mm_server_up; then up=1; fi
    sid=$(mm_session_id "$old")
    line=$(mm_def_line "$old")
    if [ -n "$line" ]; then mm_read_def "$line"; fi
    if [ -z "$sid" ] && { [ -z "$line" ] || { [ "$up" = 1 ] && [ "$d_permanent" = 0 ]; }; }; then
        mm_release_lock
        echo "macmosh-host: no such desk: $old" >&2
        mm_log desk-rename "no such desk: $old"
        return 4
    fi
    # The new name is taken by an open desk, a permanent one, or, with no server, any line.
    taken=$(mm_def_line "$new")
    if [ -n "$taken" ]; then mm_read_def "$taken"; fi
    if [ "$old" = "$new" ] || [ -n "$(mm_session_id "$new")" ] ||
        { [ -n "$taken" ] && { [ "$d_permanent" != 0 ] || [ "$up" = 0 ]; }; }; then
        mm_release_lock
        echo "macmosh-host: the desk $new already exists" >&2
        mm_log desk-rename "refused: $new already exists"
        return 7
    fi
    if [ -n "$sid" ] && ! mm_tmux rename-session -t "$sid" -- "$new" >/dev/null 2>&1; then
        mm_release_lock
        echo "macmosh-host: could not rename the desk $old" >&2
        mm_log desk-rename "failed: the session $old was not renamed"
        return 1
    fi
    # The list: the old name's line gets the new name, and a leftover line for the new name goes.
    # substr keeps the rest of the line byte for byte.
    file=$(mm_desks_file)
    if [ -f "$file" ]; then
        tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
        if ! awk -F '\t' -v o="$old" -v n="$new" '
                ($1 "") == (n "") { next }
                ($1 "") == (o "") { print n substr($0, length($1) + 1); next }
                { print }' "$file" > "$tmp" || ! mv "$tmp" "$file"; then
            rm -f "$tmp"
            # Put the session's name back, so the desk and its definition still agree.
            if [ -n "$sid" ]; then mm_tmux rename-session -t "$sid" -- "$old" >/dev/null 2>&1; fi
            mm_release_lock
            echo "macmosh-host: could not write the desk list" >&2
            mm_log desk-rename "failed: $old could not be saved"
            return 1
        fi
    fi
    mm_release_lock
    mm_log desk-rename "renamed $old to $new"
    return 0
}

# Run by the desk server's session-closed hook (see mm_set_hook), a moment after a desk's session
# closed: removes the desk's definition, unless the desk is permanent. When anything is unclear the
# definition stays, because a definition removed by mistake is a desk that won't come back after a
# restart, while one kept by mistake is only a name that desk-new replaces and the menu doesn't show.
# It stays when: another server answers or none does (the server went away: a restart, kill-server,
# a signal), nobody is logged in at the screen (logging out), the desk is open again, or it is permanent.
cmd_desk_closed() {
    local name pid line
    [ $# -eq 2 ] || mm_usage_error desk-closed "usage: desk-closed <desk> <desk server pid>"
    name="$1"
    pid="$2"
    if ! mm_valid_desk_name "$name"; then
        mm_log desk-closed "ignored: not a desk name"
        return 0
    fi
    case "$pid" in
        '' | *[!0-9]*)
            mm_log desk-closed "kept $name: no server pid"
            return 0
            ;;
    esac
    [ -n "$(mm_def_line "$name")" ] || return 0
    if [ "$(mm_server_pid)" != "$pid" ]; then
        mm_log desk-closed "kept $name: the desk server went away"
        return 0
    fi
    if ! mm_lock; then
        mm_log desk-closed "kept $name: could not lock the desk list"
        return 1
    fi
    # Read again under the lock: desk-new or desk-remove may have changed the line in the meantime.
    line=$(mm_def_line "$name")
    if [ -z "$line" ]; then
        mm_release_lock
        return 0
    fi
    mm_read_def "$line"
    if [ "$d_permanent" != 0 ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: permanent"
        return 0
    fi
    if mm_session_exists "$name"; then
        mm_release_lock
        mm_log desk-closed "kept $name: open again"
        return 0
    fi
    # Last, the screen and the server once more, just before the write: has-session also fails when the
    # server has just gone, and a logout or shutdown may have begun while this waited for the lock.
    if [ -z "$(mm_console_user)" ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: nobody is logged in at the screen"
        return 0
    fi
    if [ "$(mm_server_pid)" != "$pid" ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: the desk server went away"
        return 0
    fi
    if ! mm_drop_def_line "$name"; then
        mm_release_lock
        mm_log desk-closed "kept $name: could not write the desk list"
        return 1
    fi
    mm_release_lock
    mm_log desk-closed "removed $name: its last shell exited"
    return 0
}

cmd_window_new() {
    local name sid
    [ $# -eq 1 ] || mm_usage_error window-new "usage: window-new <desk>"
    name="$1"
    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log window-new "no such desk"
        return 4
    fi
    mm_require_server window-new
    mm_set_hook
    sid=$(mm_session_id "$name")
    if [ -z "$sid" ]; then
        echo "macmosh-host: the desk $name isn't open" >&2
        mm_log window-new "no such desk: $name"
        return 4
    fi
    if ! mm_tmux new-window -t "$sid:" >/dev/null 2>&1; then
        echo "macmosh-host: could not add a window" >&2
        mm_log window-new "failed: $name"
        return 1
    fi
    mm_log window-new "added a window to $name"
    return 0
}

cmd_attach() {
    local name="" cc=0 dry=0 npos=0 line sid
    while [ $# -gt 0 ]; do
        case "$1" in
            --cc) cc=1 ;;
            --dry-run) dry=1 ;;
            --*) mm_usage_error attach "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                [ "$npos" -le 1 ] || mm_usage_error attach "too many arguments"
                name="$1"
                ;;
        esac
        shift
    done
    [ "$npos" -eq 1 ] || mm_usage_error attach "usage: attach [--cc] [--dry-run] <desk>"

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log attach "no such desk"
        return 4
    fi
    mm_require_server attach
    mm_set_hook

    # A closed desk that still has its definition (a permanent desk, or one that ended with the
    # server) is made again from it, under the desk list's lock, so the exit path can't remove the
    # definition between the read and the new session.
    if ! mm_session_exists "$name"; then
        if ! mm_lock; then
            echo "macmosh-host: could not lock the desk list" >&2
            mm_log attach "failed: lock"
            return 1
        fi
        line=$(mm_def_line "$name")
        if [ -z "$line" ]; then
            mm_release_lock
            echo "macmosh-host: no such desk: $name" >&2
            mm_log attach "no such desk: $name"
            return 4
        fi
        mm_read_def "$line"
        if ! mm_session_exists "$name" && ! mm_create_session "$name" "$d_folder" "$d_command" "$d_keep"; then
            mm_release_lock
            echo "macmosh-host: could not open the desk $name" >&2
            mm_log attach "failed: $name could not be created"
            return 1
        fi
        mm_release_lock
    fi

    if [ "$dry" = 1 ]; then
        echo ok
        mm_log attach "dry run $name"
        return 0
    fi
    # By id, looked up last: a desk that closed since the check above is no desk to attach to.
    sid=$(mm_session_id "$name")
    if [ -z "$sid" ]; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log attach "no such desk: $name"
        return 4
    fi
    mm_log attach "$name"
    # The terminal may itself be inside another tmux; the desk server is a separate one.
    unset TMUX
    if [ "$cc" = 1 ]; then
        exec tmux -L "$MACMOSH_SOCKET" -CC attach-session -t "$sid"
    fi
    exec tmux -L "$MACMOSH_SOCKET" attach-session -t "$sid"
}

# Runs the desk's startup command, and again each time it ends. It runs inside the desk's own shell
# (the desk types "<this script> keep <desk>"), so it reads the definition and starts nothing else:
# it never needs the desk server and never starts one.
# The pause starts at MACMOSH_KEEP_PAUSE seconds (default 5) and doubles, up to 60, while the command
# keeps ending within 10 seconds. A run of a minute or more sets it back to the start. A run in
# between leaves it as it is.
cmd_keep() {
    local name line folder command start pause next began took code stopped=0 cur locked=0
    [ $# -eq 1 ] || mm_usage_error keep "usage: keep <desk>"
    name="$1"
    line=""
    # The desk is the session this runs in, when it runs in one: the shell may read the typed
    # "keep <desk>" only after a rename. The answer counts only when it comes from the server this
    # shell runs in, whose socket $TMUX names.
    # The name and the line are read under the lock, which desk-rename holds while it changes both,
    # so they are both old or both new. Without the lock they are read as they are.
    if mm_lock; then locked=1; fi
    if [ -n "${TMUX:-}" ] && [ -n "${TMUX_PANE:-}" ]; then
        cur=$(mm_tmux display-message -p -t "$TMUX_PANE" "#{socket_path}$TAB#{session_name}" 2>/dev/null)
        if [ "${cur%%"$TAB"*}" = "${TMUX%%,*}" ]; then cur="${cur#*"$TAB"}"; else cur=""; fi
        if [ -n "$cur" ] && mm_valid_desk_name "$cur"; then
            line=$(mm_def_line "$cur")
            if [ -n "$line" ]; then name="$cur"; fi
        fi
    fi
    if [ -z "$line" ] && mm_valid_desk_name "$name"; then
        line=$(mm_def_line "$name")
    fi
    if [ "$locked" = 1 ]; then mm_release_lock; fi
    if [ -z "$line" ]; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log keep "no such desk: $name"
        return 4
    fi
    mm_read_def "$line"
    folder="$d_folder"
    command="$d_command"
    if [ -z "$command" ]; then
        echo "There is nothing to keep running in the desk $name: it has no startup command."
        mm_log keep "$name: no command"
        return 0
    fi
    start="${MACMOSH_KEEP_PAUSE:-5}"
    case "$start" in
        '' | *[!0-9]*) start=5 ;;
    esac
    [ "$start" -ge 1 ] || start=5
    if [ -d "$folder" ]; then cd "$folder" || true; fi
    mm_log keep "$name: started"

    pause="$start"
    while :; do
        began=$(date +%s)
        # Ctrl-C goes to the command. This script only has to live through it.
        trap ':' INT
        "${SHELL:-/bin/zsh}" -lc "$command"
        code=$?
        trap - INT
        took=$(($(date +%s) - began))

        printf '%s ended (exit %s). Starting it again in %s seconds. Press Ctrl-C to stop.\n' "$command" "$code" "$pause"
        stopped=0
        trap 'stopped=1' INT
        sleep "$pause"
        trap - INT
        if [ "$stopped" = 1 ]; then
            echo
            mm_log keep "$name: stopped"
            return 0
        fi

        if [ "$took" -lt 10 ]; then
            next=$((pause * 2))
            [ "$next" -le 60 ] || next=60
            [ "$next" -ge "$pause" ] || next="$pause"
            pause="$next"
        elif [ "$took" -ge 60 ]; then
            pause="$start"
        fi
    done
}

cmd_folders() {
    local folder entry name
    [ $# -eq 1 ] || mm_usage_error folders "usage: folders <folder>"
    folder=$(mm_expand_tilde "$1")
    if [ -z "$folder" ] || [ ! -d "$folder" ]; then
        echo "macmosh-host: no such folder: $1" >&2
        mm_log folders "refused: no such folder"
        return 6
    fi
    # The glob skips hidden folders. A name with a new line in it would break the one-per-line list.
    for entry in "${folder%/}"/*/; do
        [ -d "$entry" ] || continue
        name="${entry%/}"
        name="${name##*/}"
        case "$name" in
            *$'\n'*) continue ;;
        esac
        printf '%s\n' "$name"
    done | LC_ALL=C sort
    mm_log folders "ok"
    return 0
}

# ---------------------------------------------------------------- login agent, restart, removal

# Text safe to put inside a plist <string>.
mm_xml_escape() {
    printf '%s' "$1" | sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g'
}

cmd_install_agent() {
    local script agent_dir plist tmp uid status=0
    script="$MACMOSH_HOME/macmosh-host"
    # The path goes inside double quotes in a zsh command line: refuse what would break out of them.
    case "$script" in
        *'"'* | *'$'* | *'`'* | *\\*)
            echo "macmosh-host: the script's path has a character the login agent can't carry" >&2
            mm_log install-agent "refused: odd path"
            return 1
            ;;
    esac
    uid=$(id -u)
    agent_dir="$HOME/Library/LaunchAgents"
    plist="$agent_dir/$AGENT_LABEL.plist"
    tmp="$plist.$$.tmp"
    if ! mkdir -p "$agent_dir"; then
        echo "macmosh-host: cannot create $agent_dir" >&2
        mm_log install-agent "failed: no folder"
        return 1
    fi
    if ! {
        cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$AGENT_LABEL</string>
    <key>ProgramArguments</key>
    <array>
        <string>/bin/zsh</string>
        <string>-lc</string>
        <string>exec "$(mm_xml_escape "$script")" start</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>LimitLoadToSessionType</key>
    <string>Aqua</string>
</dict>
</plist>
EOF
    } > "$tmp" || ! mv "$tmp" "$plist"; then
        rm -f "$tmp"
        echo "macmosh-host: cannot write $plist" >&2
        mm_log install-agent "failed: cannot write"
        return 1
    fi
    # Unload an older copy first; it is fine if there is none.
    launchctl bootout "gui/$uid/$AGENT_LABEL" >/dev/null 2>&1
    launchctl bootstrap "gui/$uid" "$plist" || status=$?
    mm_log install-agent "exit $status"
    return "$status"
}

cmd_restart_server() {
    local yes=0 arg n=0
    for arg in "$@"; do
        case "$arg" in
            --yes) yes=1 ;;
            *) mm_usage_error restart-server "usage: restart-server --yes" ;;
        esac
    done
    [ "$yes" = 1 ] || mm_usage_error restart-server "restart-server closes every desk: add --yes to confirm"

    # Check first: with nobody at the screen the server could not come back, so close nothing.
    if [ -z "$(mm_console_user)" ]; then
        echo "Nobody is logged in at this Mac's screen, so desks can't start. Log in first." >&2
        mm_log restart-server "nobody logged in"
        return 3
    fi
    if mm_server_up; then
        mm_tmux kill-server >/dev/null 2>&1
        while mm_server_up && [ "$n" -lt 20 ]; do
            sleep 0.25
            n=$((n + 1))
        done
        if mm_server_up; then
            echo "The desk server didn't stop." >&2
            mm_log restart-server "server did not stop"
            return 5
        fi
    fi
    mm_require_server restart-server
    mm_log restart-server "ok"
    return 0
}

# Removes every line of authorized_keys that has the key as a whole field. The file is rewritten
# through a temporary file in its own folder and mv, keeps its mode, and is left alone when no
# line matches or when anything fails.
mm_remove_authorized_key() {
    local key="$1" file="$HOME/.ssh/authorized_keys" dir tmp mode removed
    [ -f "$file" ] || return 0
    dir=$(dirname "$file")
    tmp=$(mktemp "$dir/authorized_keys.XXXXXX") || return 1
    removed=$(LC_ALL=C awk -v key="$key" -v out="$tmp" '
        { hit = 0; for (i = 1; i <= NF; i++) if ($i == key) hit = 1 }
        hit { n++; next }
        { print > out }
        END { close(out); print n + 0 }
    ' "$file") || {
        rm -f "$tmp"
        return 1
    }
    if [ "$removed" = 0 ]; then
        rm -f "$tmp"
        return 0
    fi
    mode=$(/usr/bin/stat -f %Lp "$file" 2>/dev/null)
    case "$mode" in
        '' | *[!0-7]*) mode=600 ;;
    esac
    if ! chmod "$mode" "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        return 1
    fi
    return 0
}

cmd_uninstall() {
    local key="" have_key=0
    while [ $# -gt 0 ]; do
        case "$1" in
            --key)
                [ $# -ge 2 ] || mm_usage_error uninstall "--key needs a value"
                key="$2"
                have_key=1
                shift
                ;;
            *) mm_usage_error uninstall "usage: uninstall --key <base64 key>" ;;
        esac
        shift
    done
    if [ "$have_key" = 0 ] || [ "${#key}" -lt 60 ]; then
        echo "macmosh-host: uninstall needs --key with MacMosh's whole public key (at least 60 characters)" >&2
        return 2
    fi
    case "$key" in
        *[!A-Za-z0-9+/=]*)
            echo "macmosh-host: the key isn't base64" >&2
            return 2
            ;;
    esac
    # Never delete a folder that could hold more than MacMosh's own files.
    case "$MACMOSH_HOME" in
        '' | / | "$HOME" | "$HOME/")
            echo "macmosh-host: refusing to remove $MACMOSH_HOME" >&2
            return 1
            ;;
    esac

    # The key first: if that fails, nothing else has been touched.
    if ! mm_remove_authorized_key "$key"; then
        echo "macmosh-host: could not update ~/.ssh/authorized_keys; nothing was removed" >&2
        return 1
    fi
    launchctl bootout "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1
    rm -f "$HOME/Library/LaunchAgents/$AGENT_LABEL.plist"
    # The desk server and open desks keep running. The log lives in the folder being emptied,
    # so this subcommand logs nothing: a log line would bring the folder back.
    # Remove only the names MacMosh makes there; a folder named by an environment variable
    # may hold other things.
    rm -f "$MACMOSH_HOME/macmosh-host" "$MACMOSH_HOME/macmosh-host.new" \
        "$MACMOSH_HOME/tmux.conf" "$MACMOSH_HOME/$DESKS_FILE_NAME" "$MACMOSH_HOME/host.log" \
        "$MACMOSH_HOME/$DESKS_FILE_NAME".*.tmp "$MACMOSH_HOME/host.log".*.tmp
    rmdir "$MACMOSH_HOME/lock" 2>/dev/null
    if [ -e "$MACMOSH_HOME" ] && ! rmdir "$MACMOSH_HOME" 2>/dev/null; then
        echo "macmosh-host: kept $MACMOSH_HOME because it holds files MacMosh didn't put there" >&2
    fi
    return 0
}

# ---------------------------------------------------------------- status

# A value from the "AC Power:" section of `pmset -g custom`: the first whole number after the name.
mm_power_value() {
    # $1 setting name, $2 the pmset text
    local v
    v=$(printf '%s\n' "$2" | awk -v key="$1" '
        /^AC Power:/ { ac = 1; next }
        /^[^ \t]/ { ac = 0 }
        ac && $1 == key {
            for (i = 2; i <= NF; i++) if ($i ~ /^[0-9]+$/) { print $i; exit }
        }')
    if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "-"; fi
}

# The lid-closed setting (`pmset -a disablesleep`). `pmset -g custom` never lists it; plain `pmset -g`
# has a line " SleepDisabled", two tabs and the number once it has been turned on (seen on macOS 27.3).
# Prints that number, or "-" when the line is absent or has no number.
mm_lid_value() {
    # $1 the text of `pmset -g`
    local v
    v=$(printf '%s\n' "$1" | awk '
        $1 == "SleepDisabled" && $2 ~ /^[0-9]+$/ { print $2; exit }')
    if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "-"; fi
}

# 255.255.255.0 -> 24. Prints nothing for anything that is not a dotted mask.
mm_mask_to_prefix() {
    local mask="$1" a b c d bits=0 octet
    case "$mask" in
        *[!0-9.]* | '') return 0 ;;
    esac
    IFS=. read -r a b c d <<EOF
$mask
EOF
    for octet in "$a" "$b" "$c" "$d"; do
        case "$octet" in
            '' | *[!0-9]*) return 0 ;;
        esac
        [ "$octet" -le 255 ] || return 0
        while [ "$octet" -gt 0 ]; do
            bits=$((bits + (octet & 1)))
            octet=$((octet >> 1))
        done
    done
    printf '%s' "$bits"
}

# A hex mask such as 0xffffff00 -> 24.
mm_hexmask_to_prefix() {
    local hex="${1#0x}" value bits=0
    case "$hex" in
        '' | *[!0-9a-fA-F]*) return 0 ;;
    esac
    value=$((16#$hex))
    while [ "$value" -gt 0 ]; do
        bits=$((bits + (value & 1)))
        value=$((value >> 1))
    done
    printf '%s' "$bits"
}

# True for 100.64.0.0/10, the range Tailscale uses.
mm_is_tailscale_address() {
    local a b rest
    IFS=. read -r a b rest <<EOF
$1
EOF
    [ "$a" = 100 ] || return 1
    case "$b" in
        '' | *[!0-9]*) return 1 ;;
    esac
    [ "$b" -ge 64 ] && [ "$b" -le 127 ]
}

mm_home_record() {
    local iface addr="" n mask prefix="" localname="" line

    iface=$(route -n get default 2>/dev/null | awk '/interface:/ { print $2; exit }')
    if [ -n "$iface" ]; then
        addr=$(ipconfig getifaddr "$iface" 2>/dev/null)
    fi
    # A tunnel (or an address in Tailscale's range) is not the home address: use the first en0..en9 that has one.
    case "$iface" in
        utun*) addr="" ;;
    esac
    if [ -n "$addr" ] && mm_is_tailscale_address "$addr"; then
        addr=""
    fi
    if [ -z "$addr" ] && [ -n "$iface" ]; then
        n=0
        while [ "$n" -le 9 ]; do
            addr=$(ipconfig getifaddr "en$n" 2>/dev/null)
            if [ -n "$addr" ]; then
                iface="en$n"
                break
            fi
            n=$((n + 1))
        done
    fi

    if [ -n "$addr" ]; then
        mask=$(ipconfig getoption "$iface" subnet_mask 2>/dev/null)
        prefix=$(mm_mask_to_prefix "$mask")
        if [ -z "$prefix" ]; then
            # A fixed address has no DHCP option: read the mask from ifconfig instead.
            line=$(ifconfig "$iface" 2>/dev/null | awk '/^[ \t]*inet / { for (i = 1; i < NF; i++) if ($i == "netmask") { print $(i + 1); exit } }')
            prefix=$(mm_hexmask_to_prefix "$line")
        fi
    fi

    localname=$(scutil --get LocalHostName 2>/dev/null)
    if [ -n "$localname" ]; then localname="$localname.local"; fi

    printf 'home\t%s\t%s\t%s\n' "$(mm_clean "$addr")" "$prefix" "$(mm_clean "$localname")"
}

mm_battery_record() {
    local text present=absent source=ac pct="-" first
    text=$(pmset -g batt 2>/dev/null)
    first=$(printf '%s\n' "$text" | head -n 1)
    case "$first" in
        *"'Battery Power'"*) source=battery ;;
    esac
    case "$text" in
        *InternalBattery*)
            present=present
            pct=$(printf '%s\n' "$text" | sed -n 's/.*[^0-9]\([0-9][0-9]*\)%.*/\1/p' | head -n 1)
            [ -n "$pct" ] || pct="-"
            ;;
    esac
    printf 'battery\t%s\t%s\t%s\n' "$present" "$source" "$pct"
}

mm_tool_record() {
    # $1 name, $2 path or empty, $3 version or empty
    printf 'tool\t%s\t%s\t%s\n' "$1" "${2:--}" "${3:--}"
}

mm_tool_records() {
    local path version

    path=$(command -v brew 2>/dev/null)
    mm_tool_record brew "$path" ""

    path=$(command -v mosh-server 2>/dev/null)
    version=""
    if [ -n "$path" ]; then
        version=$(mosh-server --version 2>&1 | sed -n 's/.*(mosh \([^)]*\)).*/\1/p' | head -n 1)
    fi
    mm_tool_record mosh-server "$path" "$version"

    path=$(command -v tmux 2>/dev/null)
    version=""
    if [ -n "$path" ]; then
        version=$(tmux -V 2>/dev/null | awk '{ print $2; exit }')
    fi
    mm_tool_record tmux "$path" "$version"
}

# The windows of one desk. A window name can hold odd characters; a line that does not start with
# "index|" is the rest of the previous name. $1 is the desk's name, $2 its session id.
mm_window_records() {
    local desk="$1" sid="$2" text
    text=$(mm_tmux list-windows -t "$sid:" -F '#{window_index}|#{window_name}' 2>/dev/null)
    printf '%s\n' "$text" | {
        local line prev=""
        while IFS= read -r line; do
            case "$line" in
                [0-9]*"|"*)
                    if [ -n "$prev" ]; then
                        printf 'window\t%s\t%s\t%s\n' "$desk" "${prev%%|*}" "$(mm_clean "${prev#*|}")"
                    fi
                    prev="$line"
                    ;;
                *) prev="$prev $line" ;;
            esac
        done
        if [ -n "$prev" ]; then
            printf 'window\t%s\t%s\t%s\n' "$desk" "${prev%%|*}" "$(mm_clean "${prev#*|}")"
        fi
    }
}

mm_desk_records() {
    local text line name rest windows attached sid
    mm_server_up || return 0
    # Format: id|name|windows|attached. A name that breaks the naming rule is left out. The windows are
    # listed by the session's id, never by "=name" (see mm_session_id).
    text=$(mm_tmux list-sessions -F '#{session_id}|#{session_name}|#{session_windows}|#{session_attached}' 2>/dev/null)
    printf '%s\n' "$text" | while IFS= read -r line; do
        sid="${line%%|*}"
        line="${line#*|}"
        case "$sid" in
            '$'[0-9]*) ;;
            *) continue ;;
        esac
        attached="${line##*|}"
        rest="${line%|*}"
        windows="${rest##*|}"
        name="${rest%|*}"
        mm_valid_desk_name "$name" || continue
        case "$windows$attached" in
            '' | *[!0-9]*) continue ;;
        esac
        printf 'desk\t%s\t%s\t%s\n' "$name" "$windows" "$attached"
        mm_window_records "$name" "$sid"
    done
}

# Every definition in the newest form, whatever form its line in desks.tsv has:
# name, reopen, keep, permanent, folder, startup command.
mm_def_records() {
    local file="$MACMOSH_HOME/desks.tsv" line
    [ -f "$file" ] || return 0
    while IFS= read -r line || [ -n "$line" ]; do
        mm_read_def "$line"
        mm_valid_desk_name "$d_name" || continue
        printf 'def\t%s\t%s\t%s\t%s\t%s\t%s\n' "$d_name" "$d_reopen" "$d_keep" "$d_permanent" "$d_folder" "$d_command"
    done < "$file"
}

cmd_status() {
    local os_version arch console server signins fv ar custom plain_pmset firewall_text sharing_line sharing agent_file
    os_version=$(sw_vers -productVersion 2>/dev/null)
    arch=$(uname -m 2>/dev/null)

    if mm_server_up; then
        server=up
        # The menu checks every 30 seconds, so a running server gets the hook soon after the script is updated.
        mm_set_hook
        # shellcheck disable=SC2016  # the command is expanded by the desk server's shell, not here
        signins=$(mm_tmux run-shell 'security show-keychain-info "$HOME/Library/Keychains/login.keychain-db" >/dev/null 2>&1 && echo ok || echo off' 2>/dev/null | head -n 1)
        case "$signins" in
            ok | off) ;;
            *) signins=unknown ;;
        esac
    else
        server=down
        signins=unknown
    fi

    case "$(fdesetup status 2>/dev/null | head -n 1)" in
        "FileVault is On"*) fv=on ;;
        "FileVault is Off"*) fv=off ;;
        *) fv=unknown ;;
    esac
    case "$(fdesetup supportsauthrestart 2>/dev/null | head -n 1)" in
        true) ar=yes ;;
        false) ar=no ;;
        *) ar=unknown ;;
    esac

    custom=$(pmset -g custom 2>/dev/null)
    plain_pmset=$(pmset -g 2>/dev/null)

    firewall_text=$(/usr/libexec/ApplicationFirewall/socketfilterfw --getglobalstate 2>/dev/null | head -n 1)
    case "$firewall_text" in
        *disabled*) firewall=off ;;
        *enabled*) firewall=on ;;
        *) firewall=unknown ;;
    esac

    sharing_line=$(launchctl print-disabled system 2>/dev/null | grep '"com.apple.screensharing"' | head -n 1)
    case "$sharing_line" in
        *"=> enabled"*) sharing=on ;;
        *"=> disabled"*) sharing=off ;;
        *) sharing=unknown ;;
    esac

    agent_file="$HOME/Library/LaunchAgents/$AGENT_LABEL.plist"

    {
        printf 'macmosh-host\t%s\t%s\n' "$MACMOSH_PROTOCOL" "$MACMOSH_HOST_VERSION"
        printf 'os\t%s\t%s\n' "$(mm_clean "$os_version")" "$(mm_clean "$arch")"
        console=$(mm_console_user)
        printf 'console\t%s\n' "$(mm_clean "$console")"
        printf 'server\t%s\n' "$server"
        printf 'signins\t%s\n' "$signins"
        printf 'filevault\t%s\n' "$fv"
        printf 'authrestart\t%s\n' "$ar"
        printf 'power\tsleep=%s\twomp=%s\tautorestart=%s\tdisablesleep=%s\n' \
            "$(mm_power_value sleep "$custom")" "$(mm_power_value womp "$custom")" \
            "$(mm_power_value autorestart "$custom")" "$(mm_lid_value "$plain_pmset")"
        mm_battery_record
        mm_home_record
        printf 'firewall\t%s\n' "$firewall"
        printf 'screensharing\t%s\n' "$sharing"
        if [ -f "$agent_file" ]; then
            printf 'agent\tinstalled\n'
        else
            printf 'agent\tmissing\n'
        fi
        mm_tool_records
        mm_desk_records
        mm_def_records
        printf 'end\n'
    }
    mm_log status "ok"
    return 0
}

# ---------------------------------------------------------------- main

usage() {
    cat >&2 <<EOF
usage: macmosh-host <subcommand>
  version   print the script version
  start     start the desk server if it is down
  status    print the status report
  attach [--cc] [--dry-run] <desk>
  desk-new <name> <folder> [--no-reopen] [--permanent] [--keep] [--command <text>]
            a new desk comes back after a restart unless --no-reopen, and is removed
            when its last shell exits unless --permanent
  desk-remove <name> [--kill]
  desk-rename <name> <new name>
            the desk keeps its windows, what runs in them and its settings
  desk-closed <desk> <pid>   run by the desk server when a desk's session closes
  keep <desk>   run the desk's startup command again each time it ends
  window-new <desk>
  folders <folder>
  install-agent
  restart-server --yes
  uninstall --key <base64 key>
EOF
}

main() {
    local sub="${1:-}"
    case "$sub" in
        version)
            echo "$MACMOSH_HOST_VERSION"
            mm_log version "ok"
            ;;
        start)
            cmd_start
            ;;
        status)
            cmd_status
            ;;
        attach)
            shift
            cmd_attach "$@"
            ;;
        desk-new)
            shift
            cmd_desk_new "$@"
            ;;
        desk-remove)
            shift
            cmd_desk_remove "$@"
            ;;
        desk-rename)
            shift
            cmd_desk_rename "$@"
            ;;
        desk-closed)
            shift
            cmd_desk_closed "$@"
            ;;
        window-new)
            shift
            cmd_window_new "$@"
            ;;
        keep)
            shift
            cmd_keep "$@"
            ;;
        folders)
            shift
            cmd_folders "$@"
            ;;
        restart-server)
            shift
            cmd_restart_server "$@"
            ;;
        uninstall)
            shift
            cmd_uninstall "$@"
            ;;
        install-agent)
            cmd_install_agent
            ;;
        *)
            usage
            mm_log "${sub:-none}" "usage error"
            return 2
            ;;
    esac
}

main "$@"

"""#
}
